	/// <summary>
	/// Supported video background viewport modes
	/// If the aspect ratio and resolution of the native video frames (see
	/// @ref VuCameraVideoMode)
	/// and the render view (see
	/// @ref VuRenderViewConfig)
	/// differ, Vuforia needs to know how it should adjust the video background image rendering with respect to the render
	/// view. The different modes control if and how Vuforia should scale the video background image and adjust the video background viewport
	/// inside the render view. The video background image will thereby always be centered.
	/// The aspect ratio of the video image is always preserved, only adjustments to the video background image scale and viewport are
	/// applied.
	/// If the aspect ratio of the render view is the same as the aspect ratio of the native video then the modes
	/// @ref VU_VIDEOBG_VIEWPORT_MODE_SCALE_TO_FILL
	/// and
	/// @ref VU_VIDEOBG_VIEWPORT_MODE_SCALE_TO_FIT
	/// will have the same result.
	/// If the aspect ratio of the render view is the same as the aspect ratio of the native video and additionally also the resolutions
	/// are the same then all three modes will have the same result.
	/// </summary>
	public enum VideoBackgroundViewportMode : int
	{
		/// <summary>
		/// Scales the video background to fill the whole render view. This can crop the video
		/// background image (either top and bottom or left and right). This is the default.
		/// </summary>
		ScaleToFill = 1,
		/// <summary>
		/// Scales the video background to show the full video image in the render view.
		/// The video background viewport is adjusted accordingly to the size of the video image
		/// in the render view which might show a letter box around the image.
		/// </summary>
		ScaleToFit = 2,
		NativeVideo = 3,
	}

