		/// <summary>
		/// The capture was paused
		/// </summary>
		Paused = 4,
		/// <summary>
		/// The capture was stopped
		/// </summary>
		Stopped = 5,
		/// <summary>
		/// The capture is generating a target from the captured data
		/// </summary>
